{
  "schemaVersion": "scene-document/v2",
  "visualDecision": {
    "mode": "scene",
    "reason": "The stated inequalities and objective determine the boundary, feasible region, corners, and minimizing corner."
  },
  "source": {
    "question": "Explain why an unbounded feasible region can have a finite minimum: minimize Z = 2x + 3y for x >= 0, y >= 0 and x + y >= 4. Show its corners and minimizing point graphically."
  },
  "quantities": [
    {"id": "cx", "value": 2},
    {"id": "cy", "value": 3},
    {"id": "b", "value": 4},
    {"id": "z0", "value": 0},
    {"id": "zmin", "value": 8}
  ],
  "entities": [
    {"id": "ax", "kind": "axes", "role": "xy-axes"},
    {"id": "A", "kind": "point", "role": "x-intercept and minimizing corner", "label": "(4, 0)"},
    {"id": "B", "kind": "point", "role": "y-intercept and corner", "label": "(0, 4)"},
    {"id": "boundary", "kind": "line", "role": "x + y = 4"},
    {"id": "feasible", "kind": "polygon", "role": "first-quadrant feasible region"}
  ],
  "constructions": [
    {"id": "kax", "operator": "axes", "inputs": {"xMin": -0.5, "xMax": 7, "yMin": -0.5, "yMax": 7}, "outputs": ["ax"]},
    {"id": "kA", "operator": "point", "inputs": {"x": 4, "y": 0, "coordinateSpace": "world"}, "outputs": ["A"]},
    {"id": "kB", "operator": "point", "inputs": {"x": 0, "y": 4, "coordinateSpace": "world"}, "outputs": ["B"]},
    {"id": "kboundary", "operator": "line", "inputs": {"start": "A", "end": "B"}, "outputs": ["boundary"]},
    {"id": "kfeasible", "operator": "linear_feasible_region", "inputs": {"variables": ["x", "y"], "constraints": ["x >= 0", "y >= 0", "x + y >= 4"], "objective": {"expression": "2*x + 3*y", "sense": "min"}}, "outputs": ["feasible"]}
  ],
  "relations": [],
  "assertions": [
    {"id": "aOnBoundary", "predicate": "on", "entities": ["A", "boundary"], "expected": true, "severity": "fatal"},
    {"id": "bOnBoundary", "predicate": "on", "entities": ["B", "boundary"], "expected": true, "severity": "fatal"}
  ],
  "annotations": [
    {"id": "boundaryLabel", "kind": "label", "targetIds": ["boundary"], "text": "x + y = 4"},
    {"id": "objective", "kind": "narration", "targetIds": ["feasible"], "text": "Minimize Z = 2x + 3y."},
    {"id": "unbounded", "kind": "narration", "targetIds": ["feasible"], "text": "The feasible region continues indefinitely in the first quadrant."},
    {"id": "minimumMark", "kind": "highlight", "targetIds": ["A"], "style": {"transient": false}},
    {"id": "minimumProof", "kind": "narration", "targetIds": ["feasible", "A"], "text": "Z = 2(x + y) + y ≥ 2(4) + 0 = 8. Equality holds at (4, 0)."}
  ],
  "requiredEntityIds": ["ax", "A", "B", "boundary", "feasible"],
  "revealGroups": [
    {"id": "setup", "entityIds": ["ax", "A", "B", "boundary", "feasible"], "dependsOn": [], "narrationCue": "Draw the boundary through both corners and show its unbounded first-quadrant feasible side."},
    {"id": "minimum", "entityIds": [], "dependsOn": ["setup"], "narrationCue": "Establish the objective lower bound, then identify the corner where equality holds."}
  ],
  "teachingTimeline": [
    {"groupId": "setup", "annotationIds": ["boundaryLabel", "objective", "unbounded"]},
    {"groupId": "minimum", "annotationIds": ["minimumMark", "minimumProof"]}
  ]
}

{
  "schemaVersion": "scene-document/v2",
  "visualDecision": {
    "mode": "scene",
    "reason": "The stated inequalities determine an exact feasible region and its two corners."
  },
  "source": {
    "question": "Explain why an unbounded feasible region can have a finite minimum: minimize Z = 2x + 3y for x >= 0, y >= 0 and x + y >= 4. Show its corners and minimizing point graphically."
  },
  "quantities": [
    {"id": "cx", "value": 2, "provenance": "given"},
    {"id": "cy", "value": 3, "provenance": "given"},
    {"id": "b", "value": 4, "provenance": "given"},
    {"id": "z0", "value": 0, "provenance": "given"},
    {"id": "zmin", "value": 8, "provenance": "derived"}
  ],
  "entities": [
    {"id": "axes", "kind": "axes", "role": "xy-coordinate axes"},
    {"id": "feasible", "kind": "linear_region", "role": "unbounded feasible region"},
    {"id": "cornerX", "kind": "point", "role": "minimizing corner", "label": "(4, 0)"},
    {"id": "cornerY", "kind": "point", "role": "other corner", "label": "(0, 4)"}
  ],
  "constructions": [
    {
      "id": "makeAxes",
      "operator": "axes",
      "inputs": {"xMin": -0.5, "xMax": 7, "yMin": -0.5, "yMax": 7},
      "outputs": ["axes"]
    },
    {
      "id": "makeFeasible",
      "operator": "linear_feasible_region",
      "inputs": {
        "variables": ["x", "y"],
        "constraints": ["x >= 0", "y >= 0", "x + y >= 4"]
      },
      "outputs": ["feasible"]
    },
    {
      "id": "makeCornerX",
      "operator": "point",
      "inputs": {"x": 4, "y": 0, "coordinateSpace": "world"},
      "outputs": ["cornerX"]
    },
    {
      "id": "makeCornerY",
      "operator": "point",
      "inputs": {"x": 0, "y": 4, "coordinateSpace": "world"},
      "outputs": ["cornerY"]
    }
  ],
  "relations": [],
  "assertions": [],
  "annotations": [
    {
      "id": "minimumHighlight",
      "kind": "highlight",
      "targetIds": ["cornerX"],
      "style": {"transient": true}
    },
    {
      "id": "minimumValue",
      "kind": "callout",
      "targetIds": ["cornerX"],
      "text": "Z_min = 8",
      "quantityId": "zmin"
    }
  ],
  "requiredEntityIds": ["axes", "feasible", "cornerX", "cornerY"],
  "revealGroups": [
    {
      "id": "setup",
      "entityIds": ["axes", "feasible"],
      "dependsOn": [],
      "narrationCue": "Graph the three inequalities. The feasible region extends indefinitely to the right and upward."
    },
    {
      "id": "corners",
      "entityIds": ["cornerX", "cornerY"],
      "dependsOn": ["setup"],
      "narrationCue": "The boundary x + y = 4 meets the axes at these two corners."
    }
  ],
  "teachingTimeline": [
    {
      "id": "showSetup",
      "revealGroupId": "setup"
    },
    {
      "id": "showCorners",
      "revealGroupId": "corners"
    },
    {
      "id": "deriveMinimum",
      "targetIds": ["cornerX"],
      "annotationIds": ["minimumHighlight", "minimumValue"],
      "narrationCue": "Throughout the feasible region, Z = 2(x + y) + y is at least 2(4) + 0 = 8. Equality holds at (4, 0), so the unbounded region has a finite minimum."
    }
  ]
}

